import{_ as p,a0 as d,w as o,s as r,I as a,x as e,a1 as n,A as l,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const E=JSON.parse('{"title":"在 FreeDOS 中使用批处理文件 | LCTT x X-CMD","titleTemplate":false,"description":"在 FreeDOS 中使用批处理文件 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 FreeDOS 中使用批处理文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 FreeDOS 中使用批处理文件 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20210407 Get started with batch files in FreeDOS","title":"在 FreeDOS 中使用批处理文件","tag":"202112","desc":""},"relativePath":"202112/20210407 Get started with batch files in FreeDOS.md","filePath":"[post].md"}'),h={name:"202112/20210407 Get started with batch files in FreeDOS.md"};function c(g,s,k,b,u,T){const i=d("Link");return o(),r("div",null,[s[27]||(s[27]=a("h1",{id:"在-freedos-中使用批处理文件",tabindex:"-1"},[e("在 FreeDOS 中使用批处理文件 "),a("a",{class:"header-anchor",href:"#在-freedos-中使用批处理文件","aria-label":"Permalink to “在 FreeDOS 中使用批处理文件”"},"​")],-1)),s[28]||(s[28]=a("blockquote",null,[a("p",null,"编写你自己的简单程序来自动执行通常需要大量输入的任务的批处理文件，是一种极好的方法。")],-1)),s[29]||(s[29]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202112/24/102751sldikuebf7z4u64l.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("在 Linux 上，创建 ",-1)),s[2]||(s[2]=a("em",null,"shell 脚本",-1)),s[3]||(s[3]=e(" 来自动执行重复的任务是很常见的。类似地，在开源版的旧式 DOS 操作系统 ",-1)),n(i,{href:"https://www.freedos.org/"},{default:l(()=>[...s[0]||(s[0]=[e("FreeDOS",-1)])]),_:1}),s[4]||(s[4]=e(" 上，你可以创建一个包含数个 FreeDOS 命令的 ",-1)),s[5]||(s[5]=a("em",null,"批处理文件",-1)),s[6]||(s[6]=e(" 。然后，你就可以运行你的批处理文件来按顺序执行每个命令。",-1))]),s[30]||(s[30]=t('<p>你可以使用一个 ASCII 文本编辑器来创建批处理文件，诸如 FeeDOS 的 Edit 应用程序。在你创建一个批处理文件后，你可以使用一个文件名称加上扩展名 <code>.bat</code> 来保存它。文件名称应该是唯一的。如果你使用 FreeDOS 的一个命令的名称作为你自己的文件名称，那么可能将会执行 FreeDOS 的命令，而不会是你的批处理文件。</p><p>实际上，所有的内部的和外部的 FreeDOS 命令都可以在一个批处理文件中使用。在你创建一个批处理文件时，你其实就是在编写一个程序。FreeDOS 批处理文件可能没有结构化编程语言的功能，但是对于耗时短暂却重复乏味的任务来说，它是非常方便的。</p><h3 id="注释你的代码" tabindex="-1">注释你的代码 <a class="header-anchor" href="#注释你的代码" aria-label="Permalink to “注释你的代码”">​</a></h3><p>对于任何程序员来说，学习的第一个好习惯都应该是：在一个程序中放置注释来解释该代码正在做什么。这是一件非常容易完成的事情，但是你需要仔细，不要傻傻地让操作系统来执行你的注释。避免出现这种情况的方法是在一个注释行的开头处放置 <code>REM</code>（“remark” 的缩写） 。</p><p>FreeDOS 忽略以 <code>REM</code> 开头的代码行。但是任何查看源文件代码（即你在你的批处理文件中所编写的文本）的人都可以读取你的注释并理解它在做什么。这也是一种临时性禁用一个命令而不需要删除它的一种方法。只需要打开你的批处理文件来进行编辑，在你想要禁用行的开头处放置 <code>REM</code> ，并保存它。在你想要重新启用这个命令时，只需要打开文件来进行编辑和移除 <code>REM</code> 。这种技巧有时被称为 “注释掉” 一个命令。</p><h3 id="开始设置" tabindex="-1">开始设置 <a class="header-anchor" href="#开始设置" aria-label="Permalink to “开始设置”">​</a></h3>',6)),a("p",null,[s[8]||(s[8]=e("在你开始编写你自己的批处理文件前，我建议在 FreeDOS 中创建一个临时目录。这将会为你提供一个处理批处理文件的安全空间，不会意外地删除、移动，或重命名重要的系统文件或目录。在 FreeDOS 上，你可以使用 ",-1)),s[9]||(s[9]=a("code",null,"MD",-1)),s[10]||(s[10]=e(" 命令来 ",-1)),n(i,{href:"https://opensource.com/article/21/2/freedos-commands-you-need-know"},{default:l(()=>[...s[7]||(s[7]=[e("创建一个目录",-1)])]),_:1}),s[11]||(s[11]=e(" ：",-1))]),s[31]||(s[31]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;MD TEMP</span></span>
<span class="line"><span>C:\\&gt;CD TEMP</span></span>
<span class="line"><span>C:\\TEMP&gt;</span></span></code></pre></div><p>FreeDOS 的 <code>ECHO</code> 命令会控制当你运行一个批处理文件时在屏幕上显示的东西。例如，这里是一个简单是单行批处理文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ECHO Hello world</span></span></code></pre></div><p>如果你创建这个文件并运行它，你将看到在屏幕上显示的句子。从命令行中完成这项操作的最快的方法是：使用 <code>COPY</code> 命令来从你的键盘中（<code>CON</code>）获取输入，并将其放置到文件 <code>TEST1.BAT</code> 之中。接下来，按下组合键 <code>Ctrl+Z</code> 来停止复制过程，按下你键盘上的 <code>Return</code> 或 <code>Enter</code> 按键来返回一个提示。</p><p>在你的临时目录中尝试创建这个文件为 <code>TEST1.BAT</code> ，接下来运行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP&gt;COPY CON TEST1.BAT</span></span>
<span class="line"><span>CON =&gt; TEST1.BAT</span></span>
<span class="line"><span>ECHO Hello world</span></span>
<span class="line"><span>^Z</span></span>
<span class="line"><span></span></span>
<span class="line"><span>C:\\TEMP&gt;TEST1</span></span>
<span class="line"><span>Hello world</span></span></code></pre></div><p>当你想要显示一段文本时，这可能很有用。例如，在一个程序完成它的任务时，你可能会在你的屏幕上看到一条告诉你需要等待的消息，或者在一个网络环境中时，你可能会看到一条登录消息。</p><p>如果你想要显示一个空行怎么办？你可能会认为 <code>ECHO</code> 命令本身就可以达到目的，但是单独一个 <code>ECHO</code> 命令只会询问 FreeDOS 来响应 <code>ECHO</code> 是打开还是关闭：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP&gt;ECHO</span></span>
<span class="line"><span>ECHO is on</span></span></code></pre></div><p>获取一个空白行的方法是在 <code>ECHO</code>后紧接着使用一个 <code>+</code>符号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP&gt;ECHO+</span></span>
<span class="line"><span></span></span>
<span class="line"><span>C:\\TEMP&gt;</span></span></code></pre></div><h3 id="批处理文件变量" tabindex="-1">批处理文件变量 <a class="header-anchor" href="#批处理文件变量" aria-label="Permalink to “批处理文件变量”">​</a></h3><p>变量是一个存储你需要你的批处理文件临时记住的信息的位置。这是编程的一个重要的功能，因为你不能总是知道你的批处理文件需要使用什么样的数据。这里有一个用于演示的简单示例。</p><p>创建 <code>TEST3.BAT</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@MD BACKUPS</span></span>
<span class="line"><span>COPY %1 BACKUPS\\%1</span></span></code></pre></div><p>变量是使用百分比符号和随后的数字表示的，因此，这个批处理文件将在你的当前目录中创建一个 <code>BACKUPS</code> 子目录，然后将复制变量 <code>%1</code> 到 <code>BACKUPS</code> 文件夹之中。这个变量是什么？当你运行批处理文件时，变量由你决定：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP&gt;TEST3 TEMP1.BAT</span></span>
<span class="line"><span>TEST1.BAT =&gt; BACKUPS\\TEST1.BAT</span></span></code></pre></div><p>你的批处理文件已经复制 <code>TEST1.BAT</code> 到一个名称为 <code>BACKUPS</code> 的子目录，因为在你运行批处理文件时，你标识这个文件为一个参数。你的批处理文件将把 <code>%1</code> 替换为 <code>TEST1.BAT</code> 。</p><p>变量是按位置的。变量 <code>%1</code> 是你提供给命令的第一个参数，变量 <code>%2</code> 是第二个参数，以此类推。假设你创建一个批处理文件来列出一个目录的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DIR %1</span></span></code></pre></div><p>尝试运行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP&gt;TEST4.BAT C:\\HOME</span></span>
<span class="line"><span>ARTICLES</span></span>
<span class="line"><span>BIN</span></span>
<span class="line"><span>CHEATSHEETS</span></span>
<span class="line"><span>GAMES</span></span>
<span class="line"><span>DND</span></span></code></pre></div><p>这像预期一样的工作。但是下面这个却失败了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP&gt;TEST4.BAT C:\\HOME C:\\DOCS</span></span>
<span class="line"><span>ARTICLES</span></span>
<span class="line"><span>BIN</span></span>
<span class="line"><span>CHEATSHEETS</span></span>
<span class="line"><span>GAMES</span></span>
<span class="line"><span>DND</span></span></code></pre></div><p>如果你尝试它，你将得到第一个参数（<code>C:\\HOME</code>）的列表，而得不到第二个参数（<code>C:\\DOCS</code>）的列表。这是因为你的批处理文件仅查找一个变量（<code>%1</code>），此外，<code>DIR</code> 命令也仅能获取一个目录。</p><p>此外，当你运行一个批处理文件时，你也不需要为其具体指定扩展名 —— 除非你运气相当不好地为批处理文件选取了一个与 FreeDOS 外部命令或类似命令相同的名称。当 FreeDOS 执行命令时，它按下面的顺序执行：</p><ol><li>内部命令</li><li>带有 *.COM 扩展名的外部命令</li><li>带有 *.EXE 扩展名的外部命令</li><li>批处理文件</li></ol><h3 id="多个参数" tabindex="-1">多个参数 <a class="header-anchor" href="#多个参数" aria-label="Permalink to “多个参数”">​</a></h3><p>好的，选择重新编写 <code>TEST4.BAT</code> 文件来使一个命令可以获取两个参数，以便你可以看到这是如何工作的。首先，使用 <code>EDIT</code> 应用程序来创建一个简单的名称为 <code>FILE1.TXT</code> 的文本文件。在其中放置一段某种类型（例如，“Hello world”）的语句，并在你的 <code>TEMP</code> 工作目录中保存文件。</p><p>接下来，使用 <code>EDIT</code> 来更改你的 <code>TEST4.BAT</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>COPY %1 %2</span></span>
<span class="line"><span>DIR</span></span></code></pre></div><p>保存它，然后执行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP\\&gt;TEST4 FILE1.TXT FILE2.TXT</span></span></code></pre></div><p>在运行你的批处理文件时，你会看一个你的 <code>TEMP</code> 目录的目录列表。在列出的文件之中，你有 <code>FILE1.TXT</code> 和 <code>FILE2.TXT</code> ，它们是由你的批处理文件所创建的。</p><h3 id="嵌套批处理文件" tabindex="-1">嵌套批处理文件 <a class="header-anchor" href="#嵌套批处理文件" aria-label="Permalink to “嵌套批处理文件”">​</a></h3><p>批处理文件的另一个功能是能够 “嵌套” ，这意味着一个批处理文件可以在另外一个批处理文件中被调用和运行。为查看这是如何工作的，从一对简单的批处理文件开始：</p><p>第一个文件被称为 <code>NBATCH1.BAT</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@ECHO OFF</span></span>
<span class="line"><span>ECHO Hello</span></span>
<span class="line"><span>CALL NBATCH2.BAT </span></span>
<span class="line"><span>ECHO world</span></span></code></pre></div><p>第一行 （<code>@ECHO OFF</code>） 轻轻地告诉批处理文件在你运行它时仅显示命令 （而不是命令本身） 的输出。你可能会在前面的示例中注意到这里有很多关于批处理文件正在做什么的反馈；在这种情况下，你正在允许你的批处理文件仅显示结果。</p><p>第二个批处理被称为 NBATCH2.BAT ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo from FreeDOS</span></span></code></pre></div><p>使用 <code>EDIT</code> 来创建这两个文件，并在你的 TEMP 子目录中保存它们。运行 <code>NBATCH1.BAT</code> 来查看会发生什么：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\TEMP\\&gt;NBATCH1.BAT </span></span>
<span class="line"><span>Hello</span></span>
<span class="line"><span>from FreeDOS</span></span>
<span class="line"><span>world</span></span></code></pre></div><p>你的第二个批处理文件将在第一个批处理文件之中通过 <code>CALL</code> 命令来执行，它将提供在你 “Hello world” 信息中间的字符串 “from FreeDOS” 。</p><h3 id="freedos-脚本" tabindex="-1">FreeDOS 脚本 <a class="header-anchor" href="#freedos-脚本" aria-label="Permalink to “FreeDOS 脚本”">​</a></h3><p>编写你自己的简单程序来自动执行通常需要大量输入的任务的批处理文件，是一种极好的方法。你使用的 FreeDOS 越多, 你将越熟悉它的命令，在你熟知命令后，在一个批处理文件中列出它们仅是一件使你的 FreeDOS 系统让你生活轻松的事情。尝试一下！</p><hr>`,47)),a("p",null,[s[13]||(s[13]=e("via: ",-1)),n(i,{href:"https://opensource.com/article/21/3/batch-files-freedos"},{default:l(()=>[...s[12]||(s[12]=[e("https://opensource.com/article/21/3/batch-files-freedos",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=e("作者：",-1)),n(i,{href:"https://opensource.com/users/ahuka"},{default:l(()=>[...s[14]||(s[14]=[e("Kevin O'Brien",-1)])]),_:1}),s[19]||(s[19]=e(" 选题：",-1)),n(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[15]||(s[15]=[e("lujun9972",-1)])]),_:1}),s[20]||(s[20]=e(" 译者：[robsean]](",-1)),n(i,{href:"https://github.com/robsean"},{default:l(()=>[...s[16]||(s[16]=[e("https://github.com/robsean",-1)])]),_:1}),s[21]||(s[21]=e(") 校对：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[17]||(s[17]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=e("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[22]||(s[22]=[e("LCTT",-1)])]),_:1}),s[25]||(s[25]=e(" 原创编译，",-1)),n(i,{href:"https://linux.cn/"},{default:l(()=>[...s[23]||(s[23]=[e("Linux中国",-1)])]),_:1}),s[26]||(s[26]=e(" 荣誉推出",-1))])])}const S=p(h,[["render",c]]);export{E as __pageData,S as default};
